mapper.select:
SELECT p.*, sc_subj.code_name AS subject_name, pu.code_name AS unit_code_name,
FROM problems p
WHERE p.problem_id = #{problemId}

SELECT p.*, sc_subj.code_name AS subject_name, pu.code_name AS unit_code_name,
FROM problems p
WHERE p.is_active = 1 AND p.level = #{level} AND p.grade = #{grade}
AND (pu.code_name LIKE CONCAT('%', #{unitName}, '%') OR pu2.code_name LIKE CONCAT('%', #{unitName}, '%') OR pu3.code_name LIKE CONCAT('%', #{unitName}, '%'))
AND (p.school_id = #{schoolId} OR p.school_id IS NULL) AND p.question_text LIKE CONCAT('%', #{keyword}, '%') ORDER BY p.created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM problems p LEFT JOIN system_codes pu ON p.unit_code_id = pu.code_id LEFT JOIN system_codes pu2 ON pu.parent_code_id = pu2.code_id LEFT JOIN system_codes pu3 ON pu2.parent_code_id = pu3.code_id WHERE p.is_active = 1 AND p.level = #{level} AND p.grade = #{grade}
AND (pu.code_name LIKE CONCAT('%', #{unitName}, '%') OR pu2.code_name LIKE CONCAT('%', #{unitName}, '%') OR pu3.code_name LIKE CONCAT('%', #{unitName}, '%'))
AND (p.school_id = #{schoolId} OR p.school_id IS NULL) AND p.question_text LIKE CONCAT('%', #{keyword}, '%')

SELECT p.*, sc_subj.code_name AS subject_name, pu.code_name AS unit_code_name,
FROM problems p
WHERE p.level = #{level} AND p.is_active = 1 ORDER BY RAND() LIMIT #{count}

SELECT p.*,
       sc_subj.code_name AS subject_name,
       pu.code_name      AS unit_code_name,

FROM problems p

WHERE 1=1
AND p.approval_status = #{approvalStatus}
AND p.level = #{level}
AND p.question_text LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM problems p
WHERE 1=1
AND p.approval_status = #{approvalStatus}
AND p.level = #{level}
AND p.question_text LIKE CONCAT('%', #{keyword}, '%')
